.aurora-btn {
  position: relative;
  padding: 2px;
  border-radius: 9999px;
  background: linear-gradient(90deg, #7928ca, #ff0080, #0070f3, #7928ca);
  background-size: 300% 300%;
  animation: aurora-flow 4s ease infinite;
  border: none;
  cursor: pointer;
  box-shadow: 0 8px 24px -4px rgba(121, 40, 202, 0.5);
  transition: transform 0.2s ease;
}
.aurora-content {
  display: block;
  padding: 12px 28px;
  background: #0a0a0f;
  color: #fff;
  border-radius: 9999px;
  font-size: 13px;
  font-weight: 600;
