}
.aurora-btn:hover {
  transform: scale(1.05);
  box-shadow: 0 12px 32px 0px rgba(255, 0, 128, 0.6);
}
.aurora-btn:active {
  transform: scale(0.98);
}
@keyframes aurora-flow {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.neu-btn {
  display: flex;
