}
.neu-btn:active {
  transform: translateY(1px);
  box-shadow: inset 4px 4px 8px #cbced5, inset -4px -4px 8px #ffffff;
}

.shimmer-btn {
  position: relative;
  padding: 12px 30px;
  background: #121217;
  color: #f3f4f6;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 100px;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.5px;
  cursor: pointer;
  overflow: hidden;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);
  transition: all 0.3s ease;
}
.shimmer-btn::before {
  content: "";
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: linear-gradient(
    60deg,
    transparent,
    rgba(255, 255, 255, 0.2),
    transparent
  );
  transform: rotate(30deg);
  animation: shimmer-sweep 3s infinite;
}
