}

.atom-loader {
  position: relative;
  width: 70px;
  height: 70px;
  display: flex;
  align-items: center;
  justify-content: center;
  perspective: 600px;
}
.atom-ring {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid transparent;
}
.ring-1 {
  border-top-color: #a855f7;
  border-bottom-color: #a855f7;
  animation: atom-spin1 1.2s linear infinite;
}
.ring-2 {
  border-left-color: #06b6d4;
  border-right-color: #06b6d4;
  animation: atom-spin2 1.5s linear infinite;
}
.ring-3 {
  border-top-color: #ec4899;
  border-right-color: #ec4899;
  animation: atom-spin3 1.8s linear infinite;
}
.atom-core {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 15px #a855f7, 0 0 30px #06b6d4;
}
@keyframes atom-spin1 {
  0% { transform: rotateX(65deg) rotateY(0deg) rotateZ(0deg); }
  100% { transform: rotateX(65deg) rotateY(0deg) rotateZ(360deg); }
}
@keyframes atom-spin2 {
  0% { transform: rotateX(0deg) rotateY(65deg) rotateZ(0deg); }
  100% { transform: rotateX(0deg) rotateY(65deg) rotateZ(360deg); }
}
@keyframes atom-spin3 {
  0% { transform: rotateX(65deg) rotateY(65deg) rotateZ(0deg); }
  100% { transform: rotateX(65deg) rotateY(65deg) rotateZ(360deg); }
}

.inf-loader {
  display: flex;
  align-items: center;
  gap: 8px;
}
.inf-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #7c3aed;
  animation: inf-bounce 1.4s ease-in-out infinite both;
}
.d1 { animation-delay: -0.32s; background: #9333ea; }
.d2 { animation-delay: -0.16s; background: #a855f7; }
.d3 { animation-delay: 0s; background: #c084fc; }
.d4 { animation-delay: 0.16s; background: #06b6d4; }
.d5 { animation-delay: 0.32s; background: #3b82f6; }

@keyframes inf-bounce {
  0%, 80%, 100% {
    transform: scale(0.4) translateY(0);
    opacity: 0.4;
  }
  40% {
    transform: scale(1.2) translateY(-10px);
    opacity: 1;
    box-shadow: 0 8px 16px rgba(147, 51, 234, 0.6);
  }
}

.cube-scene {
  width: 50px;
  height: 50px;
  perspective: 400px;
}
.cube {
  width: 100%;
  height: 100%;
  position: relative;
  transform-style: preserve-3d;
  animation: cube-spin 3s linear infinite;
}
.cube-face {
  position: absolute;
  width: 50px;
  height: 50px;
  border: 2px solid #a855f7;
  background: rgba(168, 85, 247, 0.1);
  box-shadow: inset 0 0 10px rgba(6, 182, 212, 0.4);
}
.front  { transform: rotateY(0deg) translateZ(25px); }
.back   { transform: rotateY(180deg) translateZ(25px); }
.right  { transform: rotateY(90deg) translateZ(25px); border-color: #06b6d4; }
.left   { transform: rotateY(-90deg) translateZ(25px); border-color: #06b6d4; }
.top    { transform: rotateX(90deg) translateZ(25px); border-color: #ec4899; }
.bottom { transform: rotateX(-90deg) translateZ(25px); border-color: #ec4899; }

@keyframes cube-spin {
  0% { transform: rotateX(0deg) rotateY(0deg); }
  100% { transform: rotateX(360deg) rotateY(360deg); }
}

.wave-loader {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 40px;
}
.bar {
  width: 5px;
  height: 100%;
  background: linear-gradient(to top, #7c3aed, #06b6d4);
  border-radius: 10px;
  animation: wave-bounce 1s ease-in-out infinite;
}
.b1 { animation-delay: 0.1s; }
.b2 { animation-delay: 0.2s; }
.b3 { animation-delay: 0.3s; }
.b4 { animation-delay: 0.4s; }
.b5 { animation-delay: 0.5s; }

@keyframes wave-bounce {
  0%, 100% { height: 8px; opacity: 0.4; }
  50% { height: 38px; opacity: 1; box-shadow: 0 0 12px #06b6d4; }
}

.radar-box {
  position: relative;
  width: 54px;
  height: 54px;
  border-radius: 50%;
  border: 2px solid rgba(0, 255, 204, 0.3);
  background: rgba(0, 255, 204, 0.05);
  box-shadow: 0 0 15px rgba(0, 255, 204, 0.15);
  overflow: hidden;
}
.radar-sweep {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 100%;
  background: conic-gradient(from 0deg, transparent 60%, rgba(0, 255, 204, 0.8) 100%);
  transform-origin: 0% 0%;
  animation: sweep-spin 1.6s linear infinite;
}
.radar-ping {
  position: absolute;
  top: 30%;
  left: 60%;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #00ffcc;
  box-shadow: 0 0 8px #00ffcc;
  animation: ping-fade 1.6s infinite;
}
@keyframes sweep-spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
@keyframes ping-fade {
  0%, 100% { opacity: 0; }
  50% { opacity: 1; }
}

